import 'package:freezed_annotation/freezed_annotation.dart';
import 'package:flutter/foundation.dart';

// required: associates our `main.dart` with the code generated by Freezed
part 'metafield.freezed.dart';
// optional: Since our Person class is serializable, we must add this line.
// But if Person was not serializable, we could skip it.

@freezed
class Metafield with _$Metafield {
  const factory Metafield({
    required int id,
    required int variantId,
    required String inStock,
    required String price,
    required String memberPrice,
    required String quantity,
    required String thcPercentage,
    required String cbdPercentage,
  }) = _Metafield;
  factory Metafield.fromJson(Map<String, dynamic> json) {
    List values = json["value"];
    return Metafield(
      id: json["id"],
      variantId: json["product_id"],
      inStock: values[0],
      memberPrice: values[1],
      price: values[2],
      quantity: values[3],
      thcPercentage: values[4],
      cbdPercentage: values[5],
    );
  }
}
